describe('Delete Task with Confirmation Dialog', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="task-list"]').should('be.visible');
  });

  it('should delete a task after confirming in the dialog', () => {
    cy.get('[data-testid="task-item"]').first().as('firstTask');
    cy.get('@firstTask').should('contain', 'Test Task');

    cy.get('@firstTask').find('[data-testid="delete-btn"]').click();

    cy.get('[data-testid="confirmation-dialog"]').should('be.visible');
    cy.get('[data-testid="confirmation-dialog"]').should('contain', 'Are you sure you want to delete this task?');

    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.get('[data-testid="task-item"]').should('not.contain', 'Test Task');
    cy.get('[data-testid="success-message"]').should('contain', 'Task deleted successfully');
  });

  it('should cancel deletion and keep the task when clicking cancel', () => {
    cy.get('[data-testid="task-item"]').first().as('firstTask');
    const taskText = 'Test Task';
    cy.get('@firstTask').should('contain', taskText);

    cy.get('@firstTask').find('[data-testid="delete-btn"]').click();

    cy.get('[data-testid="confirmation-dialog"]').should('be.visible');

    cy.get('[data-testid="cancel-delete-btn"]').click();

    cy.get('[data-testid="confirmation-dialog"]').should('not.exist');
    cy.get('[data-testid="task-item"]').first().should('contain', taskText);
  });

  it('should handle deletion of task with special characters in name', () => {
    cy.get('[data-testid="task-item"]').contains('Task & "Special" <Chars>').as('specialTask');

    cy.get('@specialTask').find('[data-testid="delete-btn"]').click();

    cy.get('[data-testid="confirmation-dialog"]').should('be.visible');
    cy.get('[data-testid="confirmation-dialog"]').should('contain', 'Task & "Special" <Chars>');

    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.get('[data-testid="task-item"]').should('not.contain', 'Task & "Special" <Chars>');
  });

  it('should close dialog when clicking outside of it', () => {
    cy.get('[data-testid="task-item"]').first().find('[data-testid="delete-btn"]').click();

    cy.get('[data-testid="confirmation-dialog"]').should('be.visible');

    cy.get('[data-testid="dialog-overlay"]').click({ force: true });

    cy.get('[data-testid="confirmation-dialog"]').should('not.exist');
    cy.get('[data-testid="task-item"]').first().should('exist');
  });

  it('should handle rapid delete button clicks gracefully', () => {
    cy.get('[data-testid="task-item"]').first().find('[data-testid="delete-btn"]').click();
    cy.get('[data-testid="task-item"]').first().find('[data-testid="delete-btn"]').click();

    cy.get('[data-testid="confirmation-dialog"]').should('have.length', 1);

    cy.get('[data-testid="confirm-delete-btn"]').click();

    cy.get('[data-testid="confirmation-dialog"]').should('not.exist');
  });
});
